/* Robot 2027 Offline QR Code Generator (ISO/IEC 18004 Byte Mode, Versions 1-10, ECC-L) */
(function (global) {
  "use strict";

  const EXP = new Uint8Array(512);
  const LOG = new Uint8Array(256);
  (function initGF() {
    let x = 1;
    for (let i = 0; i < 255; i++) {
      EXP[i] = x;
      LOG[x] = i;
      x <<= 1;
      if (x & 0x100) x ^= 0x11d;
    }
    for (let i = 255; i < 512; i++) EXP[i] = EXP[i - 255];
  })();

  function gfMul(a, b) {
    if (a === 0 || b === 0) return 0;
    return EXP[LOG[a] + LOG[b]];
  }

  function rsGeneratorPoly(degree) {
    let poly = [1];
    for (let i = 0; i < degree; i++) {
      const next = new Array(poly.length + 1).fill(0);
      const factor = EXP[i];
      for (let j = 0; j < poly.length; j++) {
        next[j] ^= poly[j];
        next[j + 1] ^= gfMul(poly[j], factor);
      }
      poly = next;
    }
    return poly;
  }

  function rsComputeRemainder(data, ecCount) {
    const gen = rsGeneratorPoly(ecCount);
    const res = new Uint8Array(ecCount);
    for (let i = 0; i < data.length; i++) {
      const factor = data[i] ^ res[0];
      res.copyWithin(0, 1);
      res[ecCount - 1] = 0;
      for (let j = 0; j < ecCount; j++) {
        res[j] ^= gfMul(gen[j + 1], factor);
      }
    }
    return res;
  }

  const VERSION_SPECS = [
    null,
    [1,   26,  7, 1, 19, 0,  0, []],
    [2,   44, 10, 1, 34, 0,  0, [6, 18]],
    [3,   70, 15, 1, 55, 0,  0, [6, 22]],
    [4,  100, 20, 1, 80, 0,  0, [6, 26]],
    [5,  134, 26, 1, 108, 0, 0, [6, 30]],
    [6,  172, 18, 2, 68, 0,  0, [6, 34]],
    [7,  196, 20, 2, 78, 0,  0, [6, 22, 38]],
    [8,  242, 24, 2, 97, 0,  0, [6, 24, 42]],
    [9,  292, 30, 2, 116, 0, 0, [6, 26, 46]],
    [10, 346, 18, 2, 68, 2, 69, [6, 28, 50]]
  ];

  const FORMAT_BITS_L = [
    0x77c4, 0x72f3, 0x7daa, 0x789d, 0x662f, 0x6318, 0x6c41, 0x6976
  ];

  const VERSION_BITS = {
    7: 0x07c94,
    8: 0x085bc,
    9: 0x09a99,
    10: 0x0a4d3
  };

  function encodeUtf8Bytes(str) {
    if (typeof TextEncoder !== "undefined") {
      return Array.from(new TextEncoder().encode(str));
    }
    const out = [];
    for (let i = 0; i < str.length; i++) {
      const c = str.charCodeAt(i);
      if (c < 0x80) out.push(c);
      else if (c < 0x800) out.push(0xc0 | (c >> 6), 0x80 | (c & 0x3f));
      else out.push(0xe0 | (c >> 12), 0x80 | ((c >> 6) & 0x3f), 0x80 | (c & 0x3f));
    }
    return out;
  }

  function buildDataCodewords(bytes) {
    let ver = 0;
    for (let v = 1; v <= 10; v++) {
      const spec = VERSION_SPECS[v];
      const totalDataCap = spec[3] * spec[4] + spec[5] * spec[6];
      const countBits = v <= 9 ? 8 : 16;
      const overheadBits = 4 + countBits;
      if (overheadBits + bytes.length * 8 <= totalDataCap * 8) {
        ver = v;
        break;
      }
    }
    if (!ver) throw new Error("QR payload too long (>271 bytes)");

    const spec = VERSION_SPECS[ver];
    const totalDataCap = spec[3] * spec[4] + spec[5] * spec[6];
    const bits = [];
    const pushBits = (val, len) => {
      for (let i = len - 1; i >= 0; i--) bits.push((val >>> i) & 1);
    };

    pushBits(0b0100, 4);
    pushBits(bytes.length, ver <= 9 ? 8 : 16);
    for (const b of bytes) pushBits(b, 8);

    const maxBits = totalDataCap * 8;
    const termLen = Math.min(4, maxBits - bits.length);
    pushBits(0, termLen);

    while (bits.length % 8 !== 0) bits.push(0);

    const codewords = [];
    for (let i = 0; i < bits.length; i += 8) {
      let byteVal = 0;
      for (let b = 0; b < 8; b++) byteVal = (byteVal << 1) | bits[i + b];
      codewords.push(byteVal);
    }

    const padBytes = [0xec, 0x11];
    let padIdx = 0;
    while (codewords.length < totalDataCap) {
      codewords.push(padBytes[padIdx % 2]);
      padIdx++;
    }

    const ecPerBlock = spec[2];
    const blocks = [];
    const ecBlocks = [];
    let offset = 0;
    for (let g = 0; g < 2; g++) {
      const numB = g === 0 ? spec[3] : spec[5];
      const dLen = g === 0 ? spec[4] : spec[6];
      for (let b = 0; b < numB; b++) {
        const slice = codewords.slice(offset, offset + dLen);
        offset += dLen;
        blocks.push(slice);
        ecBlocks.push(rsComputeRemainder(slice, ecPerBlock));
      }
    }

    const finalStream = [];
    const maxDataLen = Math.max(...blocks.map(b => b.length));
    for (let i = 0; i < maxDataLen; i++) {
      for (const b of blocks) {
        if (i < b.length) finalStream.push(b[i]);
      }
    }
    for (let i = 0; i < ecPerBlock; i++) {
      for (const eb of ecBlocks) {
        finalStream.push(eb[i]);
      }
    }

    return { ver, finalStream };
  }

  function createMatrix(ver) {
    const size = ver * 4 + 17;
    const modules = Array.from({ length: size }, () => new Uint8Array(size));
    const isFunc = Array.from({ length: size }, () => new Uint8Array(size));

    const setFunc = (r, c, dark) => {
      if (r < 0 || r >= size || c < 0 || c >= size) return;
      modules[r][c] = dark ? 1 : 0;
      isFunc[r][c] = 1;
    };

    const drawFinder = (top, left) => {
      for (let dr = -1; dr <= 7; dr++) {
        for (let dc = -1; dc <= 7; dc++) {
          const r = top + dr;
          const c = left + dc;
          if (r < 0 || r >= size || c < 0 || c >= size) continue;
          const inOuter = dr >= 0 && dr <= 6 && dc >= 0 && dc <= 6;
          const onBorder = dr === 0 || dr === 6 || dc === 0 || dc === 6;
          const inCore = dr >= 2 && dr <= 4 && dc >= 2 && dc <= 4;
          setFunc(r, c, inOuter && (onBorder || inCore));
        }
      }
    };

    drawFinder(0, 0);
    drawFinder(0, size - 7);
    drawFinder(size - 7, 0);

    const centers = VERSION_SPECS[ver][7];
    for (let i = 0; i < centers.length; i++) {
      for (let j = 0; j < centers.length; j++) {
        const cr = centers[i];
        const cc = centers[j];
        if ((i === 0 && j === 0) || (i === 0 && j === centers.length - 1) || (i === centers.length - 1 && j === 0)) {
          continue;
        }
        for (let dr = -2; dr <= 2; dr++) {
          for (let dc = -2; dc <= 2; dc++) {
            const dark = Math.max(Math.abs(dr), Math.abs(dc)) !== 1;
            setFunc(cr + dr, cc + dc, dark);
          }
        }
      }
    }

    for (let i = 8; i < size - 8; i++) {
      if (!isFunc[6][i]) setFunc(6, i, i % 2 === 0);
      if (!isFunc[i][6]) setFunc(i, 6, i % 2 === 0);
    }

    setFunc(size - 8, 8, 1);
    for (let i = 0; i < 9; i++) {
      if (i !== 6) {
        isFunc[8][i] = 1;
        isFunc[i][8] = 1;
      }
    }
    for (let i = 0; i < 8; i++) {
      isFunc[8][size - 1 - i] = 1;
      if (i < 7) isFunc[size - 1 - i][8] = 1;
    }

    if (ver >= 7) {
      const vBits = VERSION_BITS[ver];
      for (let i = 0; i < 18; i++) {
        const bit = (vBits >>> i) & 1;
        const a = Math.floor(i / 3);
        const b = size - 11 + (i % 3);
        setFunc(a, b, bit);
        setFunc(b, a, bit);
      }
    }

    return { size, modules, isFunc };
  }

  function drawFormatBits(modules, size, maskIdx) {
    const fBits = FORMAT_BITS_L[maskIdx];
    for (let i = 0; i <= 5; i++) modules[8][i] = (fBits >>> i) & 1;
    modules[8][7] = (fBits >>> 6) & 1;
    modules[8][8] = (fBits >>> 7) & 1;
    modules[7][8] = (fBits >>> 8) & 1;
    for (let i = 9; i < 15; i++) modules[14 - i][8] = (fBits >>> i) & 1;

    for (let i = 0; i < 8; i++) modules[8][size - 1 - i] = (fBits >>> i) & 1;
    for (let i = 8; i < 15; i++) modules[size - 15 + i][8] = (fBits >>> i) & 1;
  }

  function applyDataAndMask(ver, stream, maskIdx) {
    const { size, modules, isFunc } = createMatrix(ver);
    const maskFn = [
      (r, c) => (r + c) % 2 === 0,
      (r, c) => r % 2 === 0,
      (r, c) => c % 3 === 0,
      (r, c) => (r + c) % 3 === 0,
      (r, c) => (Math.floor(r / 2) + Math.floor(c / 3)) % 2 === 0,
      (r, c) => ((r * c) % 2) + ((r * c) % 3) === 0,
      (r, c) => (((r * c) % 2) + ((r * c) % 3)) % 2 === 0,
      (r, c) => (((r + c) % 2) + ((r * c) % 3)) % 2 === 0
    ][maskIdx];

    let bitIdx = 0;
    const totalBits = stream.length * 8;
    let upward = true;

    for (let right = size - 1; right >= 1; right -= 2) {
      if (right === 6) right = 5;
      for (let vert = 0; vert < size; vert++) {
        const r = upward ? size - 1 - vert : vert;
        for (let j = 0; j < 2; j++) {
          const c = right - j;
          if (!isFunc[r][c]) {
            let dark = 0;
            if (bitIdx < totalBits) {
              dark = (stream[bitIdx >>> 3] >>> (7 - (bitIdx & 7))) & 1;
              bitIdx++;
            }
            if (maskFn(r, c)) dark ^= 1;
            modules[r][c] = dark;
          }
        }
      }
      upward = !upward;
    }

    drawFormatBits(modules, size, maskIdx);
    return { size, modules };
  }

  function scorePenalty(modules, size) {
    let penalty = 0;
    for (let r = 0; r < size; r++) {
      let runColor = modules[r][0], runLen = 1;
      for (let c = 1; c < size; c++) {
        if (modules[r][c] === runColor) {
          runLen++;
          if (runLen === 5) penalty += 3;
          else if (runLen > 5) penalty += 1;
        } else {
          runColor = modules[r][c];
          runLen = 1;
        }
      }
    }
    for (let c = 0; c < size; c++) {
      let runColor = modules[0][c], runLen = 1;
      for (let r = 1; r < size; r++) {
        if (modules[r][c] === runColor) {
          runLen++;
          if (runLen === 5) penalty += 3;
          else if (runLen > 5) penalty += 1;
        } else {
          runColor = modules[r][c];
          runLen = 1;
        }
      }
    }
    for (let r = 0; r < size - 1; r++) {
      for (let c = 0; c < size - 1; c++) {
        const v = modules[r][c];
        if (v === modules[r][c + 1] && v === modules[r + 1][c] && v === modules[r + 1][c + 1]) {
          penalty += 3;
        }
      }
    }
    return penalty;
  }

  function generateMatrix(text) {
    const bytes = encodeUtf8Bytes(String(text || ""));
    const { ver, finalStream } = buildDataCodewords(bytes);
    let best = null;
    let bestScore = Infinity;
    for (let m = 0; m < 8; m++) {
      const cand = applyDataAndMask(ver, finalStream, m);
      const sc = scorePenalty(cand.modules, cand.size);
      if (sc < bestScore) {
        bestScore = sc;
        best = cand;
      }
    }
    return best;
  }

  function toSvgString(text, pxSize = 160) {
    const { size, modules } = generateMatrix(text);
    const quiet = 3;
    const total = size + quiet * 2;
    let rects = "";
    for (let r = 0; r < size; r++) {
      for (let c = 0; c < size; c++) {
        if (modules[r][c]) {
          rects += `<rect x="${c + quiet}" y="${r + quiet}" width="1" height="1"/>`;
        }
      }
    }
    return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 ${total} ${total}" width="${pxSize}" height="${pxSize}" shape-rendering="crispEdges"><rect width="100%" height="100%" fill="#ffffff"/><g fill="#070b14">${rects}</g></svg>`;
  }

  function render(container, text, pxSize = 160) {
    if (!container) return;
    try {
      container.innerHTML = toSvgString(text, pxSize);
    } catch (e) {
      container.innerHTML = `<div style="color:#ef4444;font-size:12px;">Lỗi tạo QR: ${e.message}</div>`;
    }
  }

  global.RobotQR = { generateMatrix, toSvgString, render };
})(window);
